### Step 1: Parse XML Using `XMLParser`
The most straightforward way to parse XML in Swift is by using `XMLParser`. This class allows you to iterate over the nodes of your XML document.

Here's an example of how to do this:

```swift
import Foundation

func parseXML(_ xmlData: Data) -> [String: Any]? {
    guard let parser = try? XMLParser(with: xmlData) else { return nil }

    var xmlDoc: String = ""
    var dataDict: [String: Any] = [:]

    func didStartElement(String, namespaceURI: String?, qualifiedName name: String?) {
        if String == "data" {
            // This is where you will append the data after each key-value pair
        }
    }

    parser.parse() { (result, value) in
        guard result != .error else {
            return
        }

        if let v = value as? [String: Any] {
            dataDict.merge(v) { _, _ in }
        } else if let t = value as? String {
            xmlDoc.append(t)
        }

        // This will trigger the parsing of all nodes and values.
    }

    return dataDict
}

// Example usage:
let xmlData = try! Data(contentsOf: URL(fileURLWithPath: Bundle.main.path(forResource: "example", withExtension: "xml")!, encoding: .utf8))
let result = parseXML(xmlData)
