🤖 [Qwen Edge] Certainly! Implementing a stack data structure in C++ can be done using either an array or a linked list approach. Below is a simple implementation of both methods:

### 1. Using Array

```cpp
#include <iostream>

class Stack {
public:
    int *arr; // Pointer to the array
    size_t top = -1; // Top index (for stack operations)

    Stack(size_t capacity) {
        arr = new int[capacity];
    }

    ~Stack() {
        delete[] arr;
    }

    void push(int value) {
        if (top == arr.length()) throw std::runtime_error("Stack overflow");
        arr[++top] = value; // Move to the next available position
    }

    int pop() {
        if (isEmpty())
            return -1;
        int temp = arr[top--]; // Remove and move back from the top
        return temp;
    }

    int peek() const {
        if (isEmpty()) 
            throw std::runtime_error("Stack underflow");
        return arr[top];
    }

    bool isEmpty() const {
        return top == -1;
    }
};

int main() {
    Stack stack(5); // Create a stack with capacity of 5

    try {
        stack.push(10);
        stack.push(20);
        stack.push(30);

        std::cout << "Top element is: " << stack.peek() << std::endl;

        stack.pop();
        std::cout << "After popping, the top element is: " << stack.peek() << std::endl;
    } catch (const char* msg) {
        std::cerr << msg << std::endl;
    }

    return 0;
}
```

### Explanation:
- **Array Implementation**:
  - The `arr` pointer points to an array of integers.
  - The `push`, `pop`, and `peek` methods modify this array based on the top index.
  - If a `std::runtime_error` is thrown, it means the stack was full and could not add another element.

### 2. Using Linked List

```cpp
#include <iostream>

class Node {
public:
    int data;
    Node* next;

    Node(int val) : data(val), next(nullptr) {}
};

class Stack {
private:
    Node* top = nullptr; // Pointer to the top node

public:
    void push(int value) {
        Node* newNode = new Node(value); // Create a new node
        newNode->next = top; // Connect it to the previous top, or initialize if its null
        top = newNode; // Move the top pointer forward
    }

    int pop() {
        if (isEmpty()) 
            return -1;

        int temp = top->data; // Store the data of the node we're removing
        Node* tempTop = top; // Temporary variable to store the next node for cleanup

        top = top->next; // Move the top pointer forward

        delete[] tempTop; // Delete the old stack node
        return temp;
    }

    int peek() const {
        if (isEmpty()) 
            throw std::runtime_error("Stack underflow");

        return top->data;
    }

    bool isEmpty() const {
        return top == nullptr;
    }
};

int main() {
    Stack stack; // Create a stack

    try {
        stack.push(10);
        stack.push(20);
        stack.push(30);

        std::cout << "Top element is: " << stack.peek() << std::endl;

        int popped = stack.pop();
        if (popped != -1) 
            std::cout << "Popped value: " << popped << std::endl;
    } catch (const char* msg) {
        std::cerr << msg << std::endl;
    }

    return 0;
}
```

### Explanation:
- **Linked List Implementation**:
  - The `Node` class represents a node in the stack, containing an integer value and a pointer to its next node.
  - The `push`, `pop`, and `peek` methods modify this linked list based on the top index (which is represented by a dummy node).
  - If a `std::runtime_error` is thrown, it means the stack was empty.

### Conclusion:
Both implementations allow you to add elements (`push`), remove elements (`pop`/`peek`), and check if the stack is empty. The choice between an array or linked list depends on whether you need faster access times (array) versus more flexibility in memory management (linked list).

