🤖 [Qwen Edge] Certainly! Below is a simple implementation of a singly linked list in C++. This example includes basic functionalities such as creating the list, adding elements to it, removing elements by index, inserting an element at any position, and printing all the elements.

```cpp
#include <iostream>

class ListNode {
public:
    int value;
    ListNode* next;

    // Constructor for initializing a node with value and reference to its next node
    ListNode(int val) : value(val), next(nullptr) {}
};

// Function to create an empty singly linked list
ListNode* CreateEmptyList() {
    return nullptr;  // An empty list will have no head or tail, so it's null.
}

// Function to append a new element at the end of the list
void AppendElement(ListNode*& head, int value) {
    ListNode* newNode = new ListNode(value);

    if (!head) { 
        // If this is the first node (empty list), make head point to newNode
        head = newNode;
    } else {
        // Traverse through the list to find the last node and add newNode after it
        ListNode* current = head;
        while (current->next != nullptr)
            current = current->next;

        // Add new node at the end
        current->next = newNode;
    }
}

// Function to insert a new element before a given index in the list
void InsertElementAt(ListNode*& head, int value, int idx) {
    if (idx < 0 || idx > length(head)) {
        std::cout << "Error: Index out of bounds\n";
        return;
    }

    ListNode* newNode = new ListNode(value);

    if (!head) { 
        // If this is the first node, make head point to newNode
        head = newNode;
    } else {
        ListNode* current = head;

        // Traverse through the list to find the element just before the desired position
        for (int i = 0; i < idx - 1 && current->next != nullptr; ++i) 
            current = current->next;

        if (!current || !current->next) {
            std::cout << "Error: Index is out of bounds\n";
            return;
        }

        // Add new node before the desired position
        newNode->next = current->next;
        current->next = newNode;
    }
}

// Function to remove an element by index
void RemoveElementByIndex(ListNode*& head, int idx) {
    if (!head) {
        std::cout << "Error: List is empty\n";
        return;
    }

    if (idx == 0) { 
        // If we are removing the first node
        ListNode* temp = head->next;
        delete head;  // Free memory allocated for old head
        head = temp;  // Update head to point to the new head
    } else {
        ListNode* current = head;

        // Traverse through the list until the desired index is reached
        for (int i = 0; i < idx - 1 && current->next != nullptr; ++i) 
            current = current->next;

        if (!current || !current->next) {
            std::cout << "Error: Index out of bounds\n";
            return;
        }

        // Remove the element by updating the next pointer
        ListNode* toDelete = current->next;
        current->next = toDelete->next;
        delete toDelete;  // Free memory allocated for old node
    }
}

// Function to print all elements in the list
void PrintList(ListNode* head) {
    if (!head)
        std::cout << "Empty List\n";
    else {
        ListNode* current = head;

        while (current != nullptr) {
            std::cout << current->value << ' ';
            current = current->next;
        }
        std::cout << '\n';
    }
}

int main() {
    // Create an empty list
    ListNode* myList = CreateEmptyList();

    // Append elements to the list
    AppendElement(myList, 10);
    AppendElement(myList, 20);
    AppendElement(myList, 30);

    // Insert element at specific index
    InsertElementAt(myList, 5, 2);  // Inserts '5' after the second element (20)

    // Print list
    std::cout << "Original List: ";
    PrintList(myList);

    // Remove an element by index
    RemoveElementByIndex(myList, 1);

    // Print list after removal
    std::cout << "List after removing at position 1: ";
    PrintList(myList);

    return 0;
}
```

### Explanation:
- **ListNode**: This class represents a node in the singly linked list. Each node contains an integer value and a pointer to the next node.

- **CreateEmptyList()**: This function returns a null reference, indicating that the list is empty.

- **AppendElement()**: Adds a new element at the end of the list by creating a new ListNode object and appending it to the current tail of the list.

- **InsertElementAt()**: Inserts an element into the list before the node corresponding to the given index. It ensures the list remains properly ordered after insertion.

- **RemoveElementByIndex()**: Removes the element at the specified position in the list by updating the next pointers appropriately and deleting the node that was removed.

- **PrintList()**: This function prints all elements in the singly linked list, iterating through each ListNode object to print their values.

### Example Use:
1. Create an empty list.
2. Append three integer values (e.g., 10, 20, 30) into the list.
3. Insert a new element at index 2 (i.e., between the second and third elements).
4. Print both the original and modified lists to show changes.

